<?php

# @autogenerated
declare(strict_types=1);

namespace Civi\Lughauth\Features\Access\UserRoleAssignament\Domain\ValueObject\Accessor;

use Civi\Lughauth\Features\Access\UserRoleAssignament\Domain\ValueObject\UserRoleAssignamentUserVO;
use Civi\Lughauth\Features\Access\User\Domain\UserRef;

trait UserRoleAssignamentUserAccessor
{
    private UserRoleAssignamentUserVO $_user;
    public function getUser(): UserRef
    {
        return $this->_user->value();
    }
    public function user(): UserRoleAssignamentUserVO
    {
        return $this->_user;
    }
    public function isUserChanged(?self $original = null): bool
    {
        return !$this->_user->equals($original?->_user);
    }
    public function withUser(UserRoleAssignamentUserVO|UserRef $user): self
    {
        $copy = clone $this;
        $copy->_user = UserRoleAssignamentUserVO::from($user);
        return $copy;
    }
}
